@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;

/* The header, then Split's two columns, 24 apart: the setup guide
   (steps 14 apart in the design, 16 here, on the scale) and the empty state; the aside's next-step cards.
   A done step's mark is icon/success; its words say "Done" as well. */
@layer nz.patterns {
  .nzp-onboarding-page {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-6);
    min-inline-size: 0;
  }

  /* each column is the container its steps query */
  .nzp-onboarding-page-column {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-6);
    container-type: inline-size;
  }

  .nzp-onboarding-page-steps {
    display: flex;
    flex-direction: column;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* the mark, the words, then the action: under the words in a narrow column, at the row's end
     from 30rem */
  .nzp-onboarding-page-step {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    gap: var(--nz-space-2) var(--nz-space-4);
    padding-block: var(--nz-space-4);
    border-block-start: var(--nz-border-width-default) solid var(--nz-border-subtle);
  }

  .nzp-onboarding-page-mark {
    display: flex;
    color: var(--nz-icon-secondary);
    font-size: 1.25rem;
  }

  .nzp-onboarding-page-done .nzp-onboarding-page-mark {
    color: var(--nz-icon-success);
  }

  .nzp-onboarding-page-text {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-0-5);
  }

  .nzp-onboarding-page-step > :last-child:not(.nzp-onboarding-page-text) {
    grid-column: 2;
    justify-self: start;
  }

  @container (width >= 30rem) {
    .nzp-onboarding-page-step {
      grid-template-columns: auto minmax(0, 1fr) auto;
    }

    .nzp-onboarding-page-step > :last-child:not(.nzp-onboarding-page-text) {
      grid-column: 3;
    }
  }

  .nzp-onboarding-page-render {
    display: block;
    inline-size: 8.75rem;
    block-size: 8.75rem;
    border-radius: var(--nz-radius-xl);
    background: var(--nz-bg-muted);
  }

  .nzp-onboarding-page-media {
    display: block;
    block-size: 7rem;
    border-radius: var(--nz-radius-lg);
    background: var(--nz-bg-surface);
  }

  .nzp-onboarding-page-price {
    margin: 0;
  }
}
